export interface Lesson {
  /** What problem exists before this thing is introduced. */
  problem: string
  /** The mechanism, in plain language — not a product blurb. */
  mentalModel: string
  /** The actual Azure/Microsoft name and where it lives. */
  azureMapping: string
  /** Where this sits in the wider system: what feeds it, what it feeds, what it depends on. */
  architecture: string
  /** The real SDK/API/config shape, when the corpus actually describes one. */
  implementation?: string
  /** A decision boundary, failure mode, or exam trap, when there's a real one. */
  watchFor?: string
}

// Hand-written, corpus-grounded lessons — not excerpts. Each one is a
// synthesis of what the full corpus source says (not just the manifest's
// 500-char excerpt), structured per the constitution's first-principles
// layers (problem -> mental model -> Azure mapping -> architecture ->
// implementation -> decision boundary). implementation is omitted only
// where the corpus source genuinely has no concrete SDK/API/config detail
// to ground it in (never invented). The raw source stays available in the
// app as a collapsed reference.
